feedbackvariables.text:
P1: float([ans1, ans2]); P2: float([ans3, ans4]); P3: float([ans5, ans6]);
W: P1 - O1;
rigid: near(P2-O2, W) and near(P3-O3, W);
nok: [near(P1,g1), near(P2,g2), near(P3,g3)];
Wr: [floor(W[1]+1/2), floor(W[2]+1/2)];
/* each vertex's own move, which points are right, and the right corners in the wrong order */
mvA: [ans1, ans2] - O1; mvB: [ans3, ans4] - O2; mvC: [ans5, ans6] - O3;
okA: nok[1]; okB: nok[2]; okC: nok[3];
ong(p) := near(p, g1) or near(p, g2) or near(p, g3);
perm: ong(P1) and ong(P2) and ong(P3) and not (near(P1, P2) or near(P2, P3) or near(P1, P3));
